import { useState, useEffect, useRef, useCallback } from "react";
import "./styles/DocuTag.css";

import Navbar from "./components/Navbar";
import TagBar from "./components/TagBar";
import DocumentGrid from "./components/DocumentGrid";
import WriteModal from "./components/WriteModal";
import { fetchDocuments } from "./api/documentApi";

export default function DocuTag() {
  const [search, setSearch] = useState("");
  const [searchTags, setSearchTags] = useState([]);
  const [showWrite, setShowWrite] = useState(false);
  const [docs, setDocs] = useState([]);
  const [pageState, setPageState] = useState({
    lastId: null,
    size: 10,
    hasNext: true,
  });

  const observerRef = useRef(null);

  const loadingRef = useRef(false); // loading을 ref로

const loadDocuments = useCallback(async ({ tags, title, lastId, size, reset = false }) => {
  if (loadingRef.current) return;  // ref로 체크
  loadingRef.current = true;
  try {
    const data = await fetchDocuments({ tags, title, lastId, size });
    setDocs((prev) => reset ? data.documents : [...prev, ...data.documents]);
    setPageState((prev) => ({
      ...prev,
      lastId: data.lastId,
      hasNext: data.hasNext,
    }));
  } catch (e) {
    console.error(e);
    setPageState((prev) => ({ ...prev, hasNext: false }));
  } finally {
    loadingRef.current = false;
  }
  }, []); // ✅ 의존성 배열 비움 → 함수 재생성 안 됨

  // 최초 진입 시 조건 없이 전체 조회

  useEffect(() => {
    loadDocuments({ tags: [], title: null, lastId: null, size: 10, reset: true });
  }, []);


  // 검색 버튼 클릭
  const handleSearch = () => {
    setDocs([]);
    setPageState({ lastId: null, size: 10, hasNext: true });
    loadDocuments({
      tags: searchTags,
      title: search.trim() || null,
      lastId: null,
      size: 10,
      reset: true,
    });
  };

  // 바닥 감지 → 다음 페이지 (현재 검색 조건 유지)
  const searchRef = useRef({ tags: searchTags, title: search });

  useEffect(() => {
    searchRef.current = { tags: searchTags, title: search };
  }, [searchTags, search]);

  useEffect(() => {
  const observer = new IntersectionObserver(
      (entries) => {
        const target = entries[0];

        // ✅ 여기 로그 1 - Observer 자체가 실행되는지 확인
        console.log("👁 Observer 콜백 실행됨");
        console.log("  isIntersecting:", target.isIntersecting);
        console.log("  hasNext:", pageState.hasNext);
        console.log("  loadingRef(객체):", loadingRef);        // 항상 {} → truthy
        console.log("  loadingRef.current:", loadingRef.current); // 실제 값
        console.log("  !loadingRef:", !loadingRef);             // 항상 false ← 버그!
        console.log("  !loadingRef.current:", !loadingRef.current); // 정상

        if (target.isIntersecting && pageState.hasNext && !loadingRef.current) { // ✅ .current 추가

          // ✅ 여기 로그 2 - 조건 통과해서 실제 요청하는지 확인
          console.log("🚀 loadDocuments 호출!", {
            tags: searchRef.current.tags,
            title: searchRef.current.title,
            lastId: pageState.lastId,
          });

          loadDocuments({
            tags: searchRef.current.tags,
            title: searchRef.current.title.trim() || null,
            lastId: pageState.lastId,
            size: pageState.size,
          });
        }
      },
      { threshold: 1.0 }  // ⚠️ 여기도 확인 필요 (아래 설명)
    );

    // ✅ 여기 로그 3 - observerRef.current가 실제 DOM인지 확인
    console.log("📌 observerRef.current:", observerRef.current);

    if (observerRef.current) observer.observe(observerRef.current);
    return () => observer.disconnect();
  }, [pageState, loadingRef]);

  const handleAddTag = (tag) => {
    if (searchTags.includes(tag)) return;
    setSearchTags((prev) => [...prev, tag]);
  };

  const handleRemoveTag = (tag) => {
    setSearchTags((prev) => prev.filter((t) => t !== tag));
  };

  const handleWrite = ({ title, tags }) => {
    setDocs((prev) => [{ id: Date.now(), title, tags }, ...prev]);
    setShowWrite(false);
  };

  return (
    <div style={{ fontFamily: "'Noto Sans KR', sans-serif", minHeight: "100vh", background: "#0f0f11", color: "#e8e6e1" }}>
      <Navbar
        search={search}
        onSearchChange={setSearch}
        onWriteClick={() => setShowWrite(true)}
        onSearch={handleSearch}  // 검색 버튼 핸들러 전달
      />
      <TagBar tags={searchTags} onRemove={handleRemoveTag} onAdd={handleAddTag} />

      <main className="main">
        <div className="result-info">
          <span>{docs.length}</span>개의 문서
          {searchTags.length > 0 && <> · <span>{searchTags.join(", ")}</span> 태그 검색 중</>}
        </div>

        <DocumentGrid docs={docs} searchTags={searchTags} />

        <div ref={observerRef} style={{ height: "1px" }} />

        {loadingRef && <p style={{ textAlign: "center", color: "#888" }}>불러오는 중...</p>}
        {!pageState.hasNext && <p style={{ textAlign: "center", color: "#555" }}>마지막 페이지입니다.</p>}
      </main>

      {showWrite && (
        <WriteModal onClose={() => setShowWrite(false)} onSubmit={handleWrite} />
      )}
    </div>
  );
}
